def comps(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not seen[r][c]:
                col=g[r][c]; comp=[]; st=[(r,c)]
                while st:
                    x,y=st.pop()
                    if seen[x][y] or g[x][y]!=col: continue
                    seen[x][y]=True; comp.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<H and 0<=ny<W: st.append((nx,ny))
                out.append((comp,col))
    return out
