def group(g):
    def comps(g,bg):
        H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
        for r in range(H):
            for c in range(W):
                if g[r][c]!=bg and not seen[r][c]:
                    col=g[r][c]; comp=[]; st=[(r,c)]
                    while st:
                        x,y=st.pop()
                        if seen[x][y] or g[x][y]!=col: continue
                        seen[x][y]=True; comp.append((x,y))
                        for dx in(-1,0,1):
                            for dy in(-1,0,1):
                                nx,ny=x+dx,y+dy
                                if 0<=nx<H and 0<=ny<W and not seen[nx][ny] and g[nx][ny]==col: st.append((nx,ny))
                    out.append(comp)
        return out
    bgc=Counter(x for row in g for x in row).most_common(1)[0][0]
    objs=[o for o in comps(g,bgc)]
    groups=[]
    used=set(); 
    for o in objs:
        if any(x in used for x in o): continue
        grp=o[:]
        for other in objs:
            if any(x in used for x in other): continue
            if min(abs(a-b)+abs(c-d) for a,c in o for b,d in other)==1: grp+=other
            used.update(other)
        # monochrome subcomponents within group
        subs=[]; cnt={}
        for x,y in grp: cnt.setdefault(g[x][y],[]).append((x,y))
        for col2,cs in cnt.items():
            rs=[a for a,_ in cs]; cs2=[b for _,b in cs]
            subs.append({'cells':sorted(cs),'size':len(cs),'norm':tuple(sorted((a-min(rs),b-min(cs2)) for a,b in cs))})
        groups.append(subs)
    return bgc,groups
def norm(cells):
    rs=[a for a,_ in cells]; cs=[b for _,b in cells]
    return tuple(sorted((a-min(rs),b-min(cs)) for a,b in cells))
for p in [1,2,3,4]:
    i_=G[f'Demo pair {p} input']; o_=G[f'Demo pair {p} output']
    bgi_,gi_ = group(i_)
    bgo_,go_= group(o_)
    print('pair',p,'in groups:',[(len(g),g[0]['size'],[x['col'] for x in g]) for g in gi_])
    print('       out groups:',[(len(g),g[0]['size'],[x['col'] for x in g]) for g in go_])
    # match by norm ignoring color
    imn=[norm([c for c in gc['cells']]) for gc in gi_]
    omn=[norm([c for c in gc['cells']]) for gc in go_]
    print('   matches:')
    for n in set(imn):
        mi=[i for i,n2 in enumerate(imn) if n2==n]
        mo=[j for j,n2 in enumerate(omn) if n2==n]
        if len(mi)>0 and len(mo)>0: print('   size',n[0][1]+n[0][0]+1 if False else sum(v for v in n),' in=',mi,' out=',mo)

def gravity(g):
    H,W=len(g),len(g[0]); bgc=Counter(x for row in g for x in row).most_common(1)[0][0]
    # find objects by color-connected components
    seen=[[False]*W for _ in range(H)]; objs=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bgc and not seen[r][c]:
                col=g[r][c]; comp=[]; st=[(r,c)]
                while st:
                    x,y=st.pop()
                    if seen[x][y] or g[x][y]!=col: continue
                    seen[x][y]=True; comp.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<H and 0<=ny<W and not seen[nx][ny] and g[nx][ny]==col: st.append((nx,ny))
                objs.append({'cells':sorted(comp),'col':col})
    res=[row[:] for row in [bgc]*H]
    for o in objs:
        rs=min(a for a,_ in o['cells']); dr=max(a-a for a,_ in o['cells'])  # drop amount needed to rest
        dr=max(0, max(0, min(h for h in [sum(1 for row in res[r_] for r_ in range(H) if False)])... ))
    # simple gravity: each object falls independently: compute free column occupancy
    def occ(): return [(r,c) for r in range(H) for c in range(W) if res[r][c]!=bgc]
    for o in objs:
        cells=o['cells']
        # translate vertically only: keep col span
        def hit(o, dr):
            s=set()
            for r,c in o['cells']: 
                nr=r+dr
                if 0<=nr<H: s.add(nr)
            # check whether shifted object intersects existing non-bg
            for nr,nc in [(r+dr,c) for r,c in cells]:
                if nc>=W: return True
                if res[nr][nc]!=bgc: return True
            return False
        d=0
        while hit(o,d+1): d+=1
        for r,c in cells: res[r+d][c]=o['col'] if False else o['col']
    return res
for p in [2,3,4]:
    i_=G[f'Demo pair {p} input']; o_=G[f'Demo pair {p} output']
    cnt=Counter(x for row in i_ for x in row); bgc=cnt.most_common(1)[0][0]
    g=gravity(i_)
    print(p,'match:',g==o_)

