# Hypothesis: each size-1 object (marker) attaches to nearest size>=2 object, recolored to host color.
# Then each resulting cluster slides up-left (dr=-k,dc=-k) simultaneously until it would touch/overlap another cluster's CURRENT cells.
def slide(g,bg):
    comps=comps(g,bg)
    objs=[o for o in comps if len(o)>1]; mks=[o for o in comps if len(o)==1]
    clusters=[]
    mkset=set()
    for mk in mks:
        if len(mk)==1 and mk in mkset: continue
        # nearest host by min Manhattan to any host cell
        best=None
        for o in objs:
            d=min(abs(r-mr)+abs(c-mc) for mr,mc in [(a,b) for a,b in mk])
            if best is None or d<best[0]: best=(d,o)
        h,b=best
        new=h+[mk[0]]
        clusters.append(new)
        for p in h: mkset.add(p)  # prevent double counting
    # remove old hosts/marker cells from occupancy
    occ=set()
    for cl in clusters: occ |= {(p[0]+1,p[1]+1) for p in cl}  # placeholder
    # slide: try k=0..max; find max k s.t. for all clusters C translated by (-k,-k), cells within grid
    out= []
    for cl in clusters:
        ks=0
        while True:
            ks+=1
            ts={(p[0]-ks,p[1]-ks) for p in cl}
            bad=False
            for q in ts:
                if not (0<=q[0]<len(g) and 0<=q[1]<len(g[0])): bad=True; break
            if bad: break
            # collide with other clusters' current (not-yet-shifted) cells? simultaneous sliding: each cluster cannot enter cells currently occupied by others after their own shift...
            # simple: next step must not overlap any OTHER cluster's ORIGINAL cells ∪ own previous? use: ts \ cl must be disjoint from union of all other clusters' cells
            if ts & {p for C in clusters for p in C} == ts & {p for C in clusters if C!=cl for p in C}:
                pass
            else:
                # overlaps some other cluster's FINAL cells — not allowed
                break
        cl=[(p[0]-ks,p[1]-ks) for p in cl]
        out.append(cl)
    res=[[[0]*(len(g[0])) for _ in range(len(g))]]
    for p in clusters: res[p[0]][p[1]]=clusters[0][0][1]

