    def slide(clusters,grid):
        H,W=len(grid),len(grid[0])
        ks=0
        while True:
            ks+=1
            ok=True
            for C in clusters:
                ts={((p[0]-ks,p[1]-ks)) for p in C}
                if not all(0<=q[0]<H and 0<=q[1]<W for q in ts): ok=False;break
                others=[{(p[0]-ks,p[1]-ks) for p in Cl} for Cl in clusters if Cl is not C]
                if ts & set(q for o in others for q in o): ok=False;break
            if ok:
                clusters=[{ (p[0]-ks,p[1]-ks) for p in C } for C in clusters]
            else: break
        return ks
    # variant B: each cluster moves individually until adjacent to another non-bg cell or blocked
    out=[[0]*len(O[0]) for _ in range(len(O))]
    for C in clusters:
        ks=0
        while True:
            ks+=1
            ts={(p[0]-ks,p[1]-ks) for p in C}
            bad=False
            if not all(0<=q[0]<H and 0<=q[1]<W for q in ts): bad=True
            elif ts & {p for o in clusters for p in o if o!=C}: bad=True
            if not bad:
                C={(p[0]-ks,p[1]-ks) for p in C}
            else: break
    # paint
    for C in clusters:
        col=C.intersection([mk[0] for mk in mks]) if False else None
        color=next(iter(o[1] for o in [comps(I,bg)[ci.index(C)]] if any(True for _ in [1])) if False else list(comps(I,bg))[0][0][1])
        for (r,c) in C: out[r][c]=color
    return out==O
