def f(g):
    bg=collections.Counter(x for row in g for x in row).most_common(1)[0][0]
    ci=comps(g,bg)
    hosts=[o for o in ci if len(o)>=2]; mks=[o for o in ci if len(o)==1]
    # marker -> nearest host (Manhattan from marker cell to host cells)
    clusters=[]
    used=set()
    for mk in mks:
        dsc={}
        for ho in hosts:
            if any(q in used for q in ho): continue
            d=min(abs(q[0]-r)+abs(q[1]-c) for r,c in ho for q in mk)
            dsc[ho]=d
        h=min(dsc,key=dsc.get)
        clusters.append(h+[mk[0]])
        used |= set(h)
    occ=set()
    final=[]
    for cl in clusters:
        ks=0
        cur=list(cl)
        while True:
            ks+=1
            ts=(lambda P:[(q[0]-ks,q[1]-ks) for q in P])
            nxt=[ts(cur)]
            if not all(0<=r<len(g) and 0<=c<len(g[0]) for r,c in nxt[0]): break
            other=occ | set(p for C_ in clusters for p in C_ if C_ is not nxt[0])
            if {q for q in nxt[0] if q not in cur} & other: break
            cur=nxt[0]; occ |= {q for q in cur}
        final.append([(p[0],p[1]) for p in cur])
    res=[[bg for _ in range(len(g[0]))] for _ in range(len(g))]
    for cells in final:
        col=g[(cells[0][0],cells[0][1])]
        for r,c in cells: res[r][c]=col
    return res
